    int arrive = depart + ta;

    int count = 0;

    // Buses from B to A
    // Departure times from B: from 5:00 (300) to 23:59 (1439)
    // Bus departs B at time t, arrives A at t + tb
    // Simion is on the road from depart to arrive
    // The bus from B departs at t, and is on the road from t to t + tb
    // They meet if the intervals [depart, arrive] and [t, t + tb] overlap
    // Overlap condition: t < arrive && t + tb > depart
    // Also, t must be >= 300 and <= 1439

    // Find the range of t
    int t_start = max(300, depart - tb + 1);
    int t_end = min(1439, arrive - 1);

    if (t_start <= t_end) {
        // Number of buses from B that departed in [t_start, t_end]
        // Buses depart every b minutes starting from 300
        // Find first departure >= t_start
        int first = 300 + ((t_start - 300 + b - 1) / b) * b;
        if (first < t_start) first += b;
        // Find last departure <= t_end
        int last = 300 + ((t_end - 300) / b) * b;
        if (first <= last) {
            count += (last - first) / b + 1;
        }
    }

    cout << count << endl;

    return 0;
