    int mm = stoi(s.substr(3, 2));
    int start = hh * 60 + mm;
    int end = start + ta;

    int count = 0;

    // Buses from B to A that depart before Simion arrives at B (end)
    // and arrive after Simion departs from A (start)
    // Bus departs B at time t, arrives A at t + tb
    // Need t < end and t + tb > start => t > start - tb
    // So t in (start - tb, end)
    // Buses depart every b minutes starting from 5:00 AM (300) to 11:59 PM (23*60+59)

    int first_bus = 300; // 5:00 AM
    int last_bus = 23 * 60 + 59; // 11:59 PM

    // Find first bus from B that departs after (start - tb)
    int t_start = start - tb + 1; // t > start - tb
    int t_end = end - 1; // t < end

    if (t_start <= t_end) {
        // Find first bus >= t_start
        int first = first_bus;
        if (first < t_start) {
            int diff = t_start - first;
            int steps = diff / b;
            first += steps * b;
            if (first < t_start) first += b;
        }
        // Find last bus <= t_end
        int last = first_bus;
        if (last < t_end) {
            int diff = t_end - last;
            int steps = diff / b;
            last += steps * b;
        }
        if (first <= last && first >= first_bus && last <= last_bus) {
            count = (last - first) / b + 1;
        }
    }

    cout << count << endl;
    return 0;
